const {spawn} = require("node:child_process");
const {chromium} = require("/deps/playwright");
(async () => {
 const server=spawn(process.execPath,["scripts/serve.mjs","--host","0.0.0.0","--port","4185"],{stdio:["ignore","pipe","pipe"]});
 let browser;
 const errors=[];
 try {
  await Promise.race([new Promise((resolve,reject)=>{server.stdout.once("data",resolve);server.once("error",reject);server.once("exit",c=>reject(new Error("server exit "+c)));}),new Promise((_,reject)=>setTimeout(()=>reject(new Error("start timeout")),5000).unref())]);
  browser=await chromium.launch({headless:true});
  const context=await browser.newContext({viewport:{width:390,height:844}});
  const page=await context.newPage();
  page.on("pageerror",e=>errors.push(e.message));
  const requests=[];
  page.on("request",r=>requests.push(r.url()));
  await page.goto("http://localhost:4185");
  const count=page.locator("#count");
  assert.equal(await count.textContent(),"0");
  await page.keyboard.press("Tab");
  assert.equal(await page.locator(":focus").textContent(),"加一");
  await page.keyboard.press("Enter");assert.equal(await count.textContent(),"1");
  await page.keyboard.press("Space");assert.equal(await count.textContent(),"2");
  await page.keyboard.press("Tab");assert.equal(await page.locator(":focus").textContent(),"减一");
  await page.keyboard.press("Enter");assert.equal(await count.textContent(),"1");
  await page.keyboard.press("Tab");assert.equal(await page.locator(":focus").textContent(),"归零");
  await page.keyboard.press("Space");assert.equal(await count.textContent(),"0");
  const burst=await page.evaluate(()=>{
   const out=document.querySelector("#count"),plus=document.querySelector("[data-action=increment]"),minus=document.querySelector("[data-action=decrement]");
   for(let i=1;i<=1000;i++){plus.click();if(out.textContent!==String(i))throw Error("increment "+i);}
   for(let i=999;i>=-250;i--){minus.click();if(out.textContent!==String(Math.max(0,i)))throw Error("decrement "+i);}
   return {increments:1000,decrements:1250,final_count:out.textContent};
  });
  await page.getByRole("button",{name:"加一",exact:true}).click();
  assert.equal(await count.textContent(),"1");
  const second=await context.newPage();await second.goto("http://localhost:4185");assert.equal(await second.locator("#count").textContent(),"0");assert.equal(await count.textContent(),"1");
  await page.reload();assert.equal(await count.textContent(),"0");
  await page.getByRole("button",{name:"加一",exact:true}).click();assert.equal(await count.textContent(),"1");
  assert.deepEqual(errors,[]);
  assert.ok(requests.every(u=>new URL(u).origin==="http://localhost:4185"));
  console.log(JSON.stringify({probe_id:"DISC-BROWSER-LIFECYCLE",target_commit:"cd8a21cf3e5cd919e78aad0a1516d2a517649d38",status:"passed",browser:browser.version(),origin:"http://localhost:4185",viewport:"390x844",keyboard_sequence:[0,1,2,1,0],burst,isolated_pages:true,reload_resets_to_zero:true,reload_single_listener:true,page_errors:errors,requests},null,2));
 } finally {if(browser)await browser.close();server.kill("SIGTERM");}
})().catch(e=>{console.error(e);process.exitCode=1;});'\'''

